def cf_expansion(n, d):
    e = []

    q = n // d
    r = n % d
    e.append(q)

    while r != 0:
        n, d = d, r
        q = n // d
        r = n % d
        e.append(q)

    return e

def convergents(e):
    n = [] # Nominators
    d = [] # Denominators

    for i in range(len(e)):
        if i == 0:
            ni = e[i]
            di = 1
        elif i == 1:
            ni = e[i]*e[i-1] + 1
            di = e[i]
        else: # i > 1
            ni = e[i]*n[i-1] + n[i-2]
            di = e[i]*d[i-1] + d[i-2]

        n.append(ni)
        d.append(di)
        yield (ni, di)

def solve(phi, n):
    b = (phi - n - 1)
    D = iroot(pow(phi - n - 1, 2)-4*n, 2)[0]
    return ((-b +  D) // 2, (-b - D) // 2)

exp_lst = cf_expansion(e, n)
for i in convergents(exp_lst):
    k, d = i
    if(k == 0):
        continue
    
    phi = e*d//k
    p, q = solve(phi, n)
    if(p*q == n):
        print(long_to_bytes(pow(c, d, n)))
        break